def backfill_due_times(apps, schema_editor):
    """Tickets opened before Phase 7 get SLA due times from their creation and priority."""
    from datetime import timedelta

    first = settings.SUPPORT_FIRST_RESPONSE_SLA_MINUTES
    resolve = settings.SUPPORT_RESOLUTION_SLA_HOURS
    SupportTicket = apps.get_model("support", "SupportTicket")
    for ticket in SupportTicket.objects.filter(first_response_due_at__isnull=True).iterator():
        ticket.first_response_due_at = ticket.created_at + timedelta(
            minutes=int(first.get(ticket.priority, 60))
        )
        ticket.resolution_due_at = ticket.created_at + timedelta(
            hours=int(resolve.get(ticket.priority, 24))
        )
        ticket.save(update_fields=["first_response_due_at", "resolution_due_at"])


